class TerminalWriter(object):
    """Wrapper of `print` that can write to stdout or to a file."""
    def __init__(self, redirection_type=RedirectionType.append,
                 redirection_file_path=None):
        self.redirection_file_path = redirection_file_path
        self.buffered_text = None

        self._file_mode = None
        self.set_redirection_type(redirection_type)

    def reset(self):
        self.redirection_file_path = None
        self.buffered_text = None
    def set_redirection_type(self, redirection_type):
        """
        Sets redirection type.
        @pre: `redirection_type` is of type `RedirectionType`.
        """
        if redirection_type == RedirectionType.append:
            self._file_mode = 'a+'
        elif redirection_type == RedirectionType.truncate:
            self._file_mode = 'w+'
        elif redirection_type == RedirectionType.quiet:
            self._file_mode = 'quiet'

    def get_redirection(self):
        """
        Returns a 2-tuple containing the type and file path of the redirection.
        If this wrapper doesn't redirect to any file (or ignore prints),
        returns `None`.
        """
        if self._file_mode is None:
            return None
        if self._file_mode == 'quiet':
            return (RedirectionType.quiet, None)
        if self._file_mode == 'a+':
            return (RedirectionType.append, self.redirection_file_path)
        if self._file_mode == 'w+':
            return (RedirectionType.truncate, self.redirection_file_path)
        return None


    def write(self, text):
        pass









    def error_log(self, text):
        processed_text = ''.join(['\t' + line + '\n'
                                  for line in text.split('\n')])
        self.write("[ERROR]"+processed_text[:-1])


    def flush(self):
        """
        Flushes the buffered text to the redirection file
        if such a file is provided.
        """
        if self.redirection_file_path is not None:
            # Create file if it doesn't exist
            if not os.path.isfile(self.redirection_file_path):
                io.open(self.redirection_file_path, 'w+').close()
            # Write to the file if needed
            if self.buffered_text is not None:
                with io.open(self.redirection_file_path, self._file_mode) as f:
                    print(self.buffered_text, '\n', sep='', file=f)
        self.buffered_text = None

def run_generation(self, adapter_str=None):
    """"
    Runs the generation of all intents and writes them out to the output
    file(s) using the adapter `adapter` if one is provided.
    @pre: the parsing has been done.
    """
    if adapter_str is None:
        adapter = self.adapter
    else:
        adapter = adapter_factory.create_adapter(adapter_str)

    self.generator = Generator()
    synonyms = AST.get_or_create().get_entities_synonyms()

    if os.path.exists(self.output_dir_path):
        if self.force_overwriting or self._ask_confirmation():
            shutil.rmtree(self.output_dir_path)
        else:
            print_DBG("Aborting generation. Exiting without any change.")
            return

    train_examples = list(self.generator.generate_train())
    if train_examples:
        adapter.write(os.path.join(self.output_dir_path, "train"),
                      train_examples, synonyms)
    test_examples = list(self.generator.generate_test(train_examples))
    if test_examples:
        adapter.write(os.path.join(self.output_dir_path, "test"),
                      test_examples, synonyms)
    print_DBG("Generation over")

def execute(self):
    """
    Executes the whole command represented by this object.
    This method can be overriden by subclasses if a different algorithm is
    required.
    """
    # TODO support variations
    if len(self.command_tokens) < 3:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " + self.usage_str
        )
        return

    unit_type = CommandStrategy.get_unit_type_from_str(self.command_tokens[1])
    if unit_type is None:
        self.print_wrapper.error_log(
            "Unknown unit type: '" + str(self.command_tokens[1]) + "'."
        )
        return

    unit_regex = self.get_regex_name(self.command_tokens[2])
    if unit_regex is None:
        try:
            [unit_name, variation_name] = \
                CommandStrategy.split_exact_unit_name(
                    self.command_tokens[2]
                )
        except SyntaxError:
            self.print_wrapper.error_log(
                "Unit identifier couldn't be interpreted. " + \
                "Did you mean to escape some hashtags '#'?")
            return
        self.execute_on_unit(unit_type, unit_name, variation_name)
    else:
        count = 0
        for unit_name in self.next_matching_unit_name(
            unit_type, unit_regex
        ):
            self.execute_on_unit(unit_type, unit_name)
            count += 1
        if count == 0:
            self.print_wrapper.write("No " + unit_type.name + " matched.")
    self.finish_execution()
